// === Tab: mySketch ===
ArrayList <particula> particulas;

function setup()
{
  createCanvas(450, 450);
  particulas = new ArrayList <particula>();

  for(i = 0; i<900; i++)
  {
    particulas.add(new particula());
  }
}

function draw()
{
  background(0);

  for(particula p: particulas)
  {
    p.display();
    p.movimiento();
  }

}

function mousePressed()
{
  particula foo = new particula((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  particulas.add(foo);

}

class particula
{
  x,y,v,a,t;
  c;

  constructor(x_, y_, v_, a_, t_, c_)
  {
    x = x_;
    y = y_;
    v = v_;
    a = a_;
    t = t_;
    c = c_;
  }

  constructor()
  {
    x = random(10);
    y = random(700);
    v = random(10);
    a = random(TWO_PI);
    t = random(1,30);
    c = color(random(550), random(250), random(250));
  }

  constructor(x_, y_)
  {
    x = x_;
    y = y_;
    v = random(5);
    a = random(TWO_PI);
    t = random(10,30);
    c = color(random(250));
  }

  function display()
  {
    pushMatrix();
    translate(x,y);
    fill(c);
    rect (0,0,t,t); 
    noStroke();
    popMatrix();
  }

  function movimiento()
  {
    x += random(-a,v);
    y -= random(-a,v);
  }
}

